// Matches ANSI escape sequences (e.g. the color codes wrapping the debug banner).
const ANSI_ESCAPE_REGEX = /\x1B\[[0-9;]*m/g;

// The banner Storybook prepends to failing story errors so users can jump into
// the story to debug. See addon-vitest's `modifyErrorMessage`.
const DEBUG_BANNER_MARKER = 'Click to debug the error directly in Storybook';

/** Strip Storybook debug banners and ANSI escape codes from an error string. */
function stripDebugBanner(text: string): string {
  return text
    .replace(ANSI_ESCAPE_REGEX, '')
    .split('\n')
    .filter((line) => !line.includes(DEBUG_BANNER_MARKER))
    .join('\n');
}

/** Return the first line of `text` that has non-whitespace content, trimmed. */
function firstNonEmptyLine(text: string): string | undefined {
  for (const line of text.split('\n')) {
    const trimmed = line.trim();
    if (trimmed.length > 0) {
      return trimmed;
    }
  }
  return undefined;
}

/**
 * Extract a concise, human readable error message from a raw error message and/or stack trace.
 *
 * - Strips Storybook debug banners (and ANSI codes) from the message.
 * - Returns the first non-empty line of the cleaned message.
 * - Falls back to the first non-empty line of the stack trace when the message is empty.
 * - Returns 'unknown error' when both the message and stack are empty or undefined.
 */
export function extractErrorMessage(
  message: string | undefined,
  stack: string | undefined
): string {
  const cleanedMessage = stripDebugBanner(message ?? '');
  const messageLine = firstNonEmptyLine(cleanedMessage);
  if (messageLine) {
    return messageLine;
  }

  const cleanedStack = stripDebugBanner(stack ?? '');
  const stackLine = firstNonEmptyLine(cleanedStack);
  if (stackLine) {
    return stackLine;
  }

  return 'unknown error';
}

/**
 * Return true if any report is a render analysis that flagged an empty render.
 */
export function detectEmptyRender(
  reports: readonly { type: string; result?: unknown }[] | undefined
): boolean {
  if (!reports) {
    return false;
  }

  return reports.some(
    (report) =>
      report.type === 'render-analysis' &&
      (report.result as { emptyRender?: boolean } | undefined)?.emptyRender === true
  );
}

